param([string]$MigrationPath='sql/updates/world/2026_10_27_16_broken_shore_class_routes.sql',[switch]$VerifyLive)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..");$out="$repo/build-extractors/runtime-test/broken-shore-route-data"
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory $out -RuntimeDirectories @($out) -Test {
 $db=(Get-Content "$repo/build-extractors/bin/Release/worldserver.conf"|Where-Object {$_ -match '^WorldDatabaseInfo\s*='}).Split('"')[1].Split(';')
 $migration=Get-Content "$repo/$MigrationPath" -Raw
 function Query([string]$sql,[bool]$refusal=$false){$prior=$env:MYSQL_PWD;$priorErrors=$ErrorActionPreference;try{$env:MYSQL_PWD=$db[3];$ErrorActionPreference='Continue';$rows=@($sql|& C:/wamp64/bin/mariadb/mariadb11.4.9/bin/mysql.exe --host=$($db[0]) --port=$($db[1]) --user=$($db[2]) --database=$($db[4]) --batch --raw --skip-column-names 2> "$out/stderr.txt");$code=$LASTEXITCODE}finally{$env:MYSQL_PWD=$prior;$ErrorActionPreference=$priorErrors};if($refusal){if(!$code -or (Get-Content "$out/stderr.txt" -Raw) -notmatch 'Map1500 class routes differ'){throw 'Expected custom-route refusal absent'};'PASS expected custom-route refusal (counterfactual)'}else{if($code -or (Get-Item "$out/stderr.txt").Length){Get-Content "$out/stderr.txt";throw 'Route data test failed'};if($rows -match '^FAIL'){throw 'Route fixture/readback differs'};$rows}}
 $setup="CREATE TEMPORARY TABLE route_shape LIKE scenario_data;CREATE TEMPORARY TABLE scenario_data LIKE route_shape;INSERT INTO scenario_data VALUES(775,1500,0,0,0,0),(933,1500,0,0,0,0),(961,1500,0,0,0,0),(999,9999,1,67,8,99);"
 $check="SELECT IF((SELECT COUNT(*) FROM scenario_data WHERE MapID=1500 AND DifficultyID=12 AND Team=0 AND ((ScenarioID=775 AND Class=2 AND LfgDungeonID=906) OR(ScenarioID=933 AND Class=1 AND LfgDungeonID=1176) OR(ScenarioID=961 AND Class=12 AND LfgDungeonID=1166)))=3,'PASS three exact class routes','FAIL routes');SELECT IF((SELECT COUNT(*) FROM scenario_data WHERE ScenarioID=999 AND MapID=9999 AND DifficultyID=1 AND Team=67 AND Class=8 AND LfgDungeonID=99)=1,'PASS unrelated route unchanged','FAIL unrelated');"
 Query ($setup+$migration+$check+$migration+$check)
 Query ($setup+"UPDATE scenario_data SET LfgDungeonID=906 WHERE ScenarioID=933;"+$migration) $true
 if($VerifyLive){$hash=(Get-FileHash "$repo/$MigrationPath" -Algorithm SHA1).Hash;Query ($check.Substring(0,$check.IndexOf(';')+1)+"SELECT IF((SELECT COUNT(*) FROM updates WHERE name='2026_10_27_16_broken_shore_class_routes.sql' AND state='RELEASED' AND hash='$hash')=1,'PASS live updater/hash','FAIL live updater/hash');")}
}
